import React from "react";

function About() {
  return (
    <section id="about" className="p-10 text-center">
      <h2 className="text-3xl font-bold mb-4">About Me</h2>
      <p className="max-w-2xl mx-auto text-lg">
        Technical Support Executive with 2+ years of experience managing ERP modules,
        training internal teams, and resolving customer issues. Skilled in Python, C/C++,
        Java, SQL, and web technologies with hands-on project experience across full-stack
        development and AI integration.
      </p>
    </section>
  );
}

export default About;
